<?php declare(strict_types=1); require_once __DIR__.'/includes/bootstrap.php'; require_once __DIR__.'/includes/media.php'; $lh_page_title='Learning Hub'; $lh_description='Practical computer, programming, AI and digital skills with SmartToolz Learning Hub.'; $courses=[];$cats=[]; try{$courses=$db->query("SELECT c.*,lc.name category_name,lc.icon category_icon,lc.slug category_slug,(SELECT COUNT(*) FROM learning_lessons l WHERE l.enabled=1 AND ((l.course_id=c.id) OR EXISTS(SELECT 1 FROM learning_chapters ch WHERE ch.id=l.chapter_id AND ch.course_id=c.id))) lesson_count FROM learning_courses c LEFT JOIN learning_categories lc ON lc.id=c.category_id WHERE c.enabled=1 ORDER BY c.featured DESC,c.id DESC")->fetchAll(PDO::FETCH_ASSOC);$cats=$db->query("SELECT * FROM learning_categories WHERE enabled=1 ORDER BY sort_order,name")->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){error_log($e->getMessage());} $lessonTotal=array_sum(array_map(fn($r)=>(int)$r['lesson_count'],$courses)); include __DIR__.'/includes/header.php'; include __DIR__.'/includes/navbar.php'; ?><div class="container-fluid"><div class="row"><div class="col-lg-3 col-xl-2 p-0"><?php include __DIR__.'/includes/sidebar.php'; ?></div><main class="col-lg-9 col-xl-10 lh-content py-4 py-lg-5"><div class="container-fluid"><section class="lh-home-hero p-4 p-md-5 mb-4"><div class="row align-items-center g-4"><div class="col-xl-7"><span class="lh-kicker"><i class="bi bi-stars"></i> SmartToolz Learning Hub</span><h1 class="display-4 fw-bold mt-3 mb-3">Learn smarter.<br><span class="lh-gradient-text">Build something real.</span></h1><p class="lead text-secondary mb-4">Practical computer skills, web development, programming, AI, design and career learning — organized into clear, step-by-step paths.</p><div class="d-flex gap-2 flex-wrap"><a class="btn btn-primary btn-lg px-4" href="/learning-hub/courses.php"><i class="bi bi-compass me-2"></i>Explore Courses</a><a class="btn btn-light btn-lg px-4 border" href="/learning-hub/practice.php"><i class="bi bi-lightning-charge me-2"></i>Practice Now</a></div><div class="lh-hero-stats mt-4"><div><strong><?=number_format(count($courses))?>+</strong><span>Courses</span></div><div><strong><?=number_format($lessonTotal)?>+</strong><span>Lessons</span></div><div><strong><?=number_format(count($cats))?></strong><span>Topics</span></div></div></div><div class="col-xl-5"><div class="lh-visual-card"><img src="/learning-hub/assets/images/courses/web.svg" width="1600" height="900" alt="SmartToolz Learning Hub" loading="eager"><div class="lh-visual-glass"><span class="lh-live-dot"></span> Learn • Practice • Build</div></div></div></div></section><section class="mb-5"><div class="d-flex justify-content-between align-items-end mb-3"><div><span class="lh-section-kicker">Explore by topic</span><h2 class="h2 fw-bold mb-1">What do you want to learn?</h2><p class="text-secondary mb-0">Pick a topic and start with a practical learning path.</p></div><a href="/learning-hub/courses.php" class="btn btn-outline-primary btn-sm">View all <i class="bi bi-arrow-right"></i></a></div><div class="row g-3"><?php foreach($cats as $cat): ?><div class="col-sm-6 col-md-4 col-xl-3"><a class="lh-topic-card h-100" href="/learning-hub/courses.php?category=<?=rawurlencode((string)$cat['slug'])?>"><span class="lh-topic-icon"><?=lh_h($cat['icon']??'📚')?></span><span class="lh-topic-copy"><strong><?=lh_h($cat['name'])?></strong><small><?=lh_h($cat['description']??'Learn practical skills.')?></small></span><i class="bi bi-arrow-up-right"></i></a></div><?php endforeach; ?></div></section><section class="mb-5"><div class="d-flex justify-content-between align-items-end mb-3"><div><span class="lh-section-kicker">Editor picks</span><h2 class="h2 fw-bold mb-1">Featured courses</h2><p class="text-secondary mb-0">Structured paths you can start today.</p></div></div><div class="row g-4"><?php foreach(array_slice($courses,0,6) as $c): ?><div class="col-md-6 col-xl-4"><a class="lh-course-card" href="/learning-hub/course.php?slug=<?=rawurlencode((string)$c['slug'])?>"><div class="lh-course-art"><img src="<?=lh_h(lh_course_image((string)($c['category_slug']??'')))?>" width="1600" height="900" alt="<?=lh_h($c['title'])?>" loading="lazy"><?php if((int)$c['featured']===1):?><span class="lh-featured"><i class="bi bi-stars"></i> Featured</span><?php endif;?></div><div class="p-4"><div class="small fw-bold text-primary mb-1"><?=lh_h($c['category_name']??'Learning Hub')?></div><h3 class="h5 fw-bold mb-2"><?=lh_h($c['title'])?></h3><p class="small text-secondary mb-3"><?=lh_h($c['description']??'Practical step-by-step learning with exercises.')?></p><div class="d-flex justify-content-between align-items-center"><span class="lh-pill"><?=lh_h($c['level']??'Beginner')?></span><span class="small fw-bold text-primary"><?=number_format((int)$c['lesson_count'])?> lessons <i class="bi bi-arrow-right"></i></span></div></div></a></div><?php endforeach; if(!$courses): ?><div class="col-12"><div class="lh-empty p-5 text-center"><div class="fs-1 mb-2">📚</div><h3 class="h5">Courses are being prepared</h3><p class="text-secondary mb-3">Please check back shortly.</p><a class="btn btn-primary" href="/learning-hub/courses.php">Browse Courses</a></div></div><?php endif; ?></div></section><section class="lh-tools-banner p-4 p-md-5 mb-5"><div class="row align-items-center g-4"><div class="col-lg-8"><span class="lh-kicker"><i class="bi bi-tools"></i> Learn by doing</span><h2 class="h2 fw-bold mt-2 mb-2">Use SmartToolz while you learn.</h2><p class="text-secondary mb-0">Generate, convert, calculate, format and test things without leaving your learning workflow.</p></div><div class="col-lg-4 text-lg-end"><a class="btn btn-primary btn-lg" href="/smart-toolz/"><i class="bi bi-grid-3x3-gap me-2"></i>Explore Smart Tools</a></div></div></section><div class="lh-ad-slot my-5">Advertisement</div></div></main></div></div><?php include __DIR__.'/includes/footer.php'; ?><script src="/learning-hub/assets/j